<template>
  <div class="container">
    <div class="main-buttons">
      <q-input
        v-model="searchBy"
        data-test="decision-tree-search"
        dense
        class="search-input"
        :class="searchBy.length === 0 ? 'search-in-active' : 'search-active'"
        autofocus
        :placeholder="$t('search_decision_tree')"
        outlined
        @update:model-value="filterTableData"
      >
        <template v-slot:append>
          <Icon icon="mdi:magnify" class="size-5 text-muted-foreground" />
        </template>
      </q-input>
      <div class="button-group">
        <f-btn
          icon="add"
          data-test="decision-tree-add-btn"
          :label="$t('add_decision_tree')"
          class="main-button"
          @click="dialog = true"
        />
        <f-btn
          icon="file_upload"
          data-test="decision-tree-import-btn"
          :label="$t('import_decision_tree')"
          class="main-button"
          @click="uploadDialog = true"
        />
      </div>
    </div>
    <Loader />
    <div class="container">
      <div class="full-width">
        <DocBitsTable
          data-test="decision-trees-table"
          :rows="filteredData || []"
          :columns="columns"
          :loading="isLoading"
          row-key="id"
          table-id="decision_trees_table"
          :features="{
            sorting: true,
            clientSideSort: true,
            filtering: false,
            selection: false,
            bulkActions: false,
            rowActions: true,
            resizable: false,
            pagination: true,
            clientSidePagination: true,
            columnReorder: false,
            columnSettings: false,
            stickyFirstColumn: false,
            stickyLastColumn: true,
          }"
          :pagination="{ page: 1, rowsPerPage: 25 }"
          :row-actions="rowActions"
          no-data-label="no_record_found"
          table-class="decision-trees-table-height"
          flat-style
          @row-action="handleRowAction"
          @row-click="handleRowClick"
        >
          <!-- Name column -->
          <template #body-cell-name="{ row }">
            <span
              :data-test="'decision-tree-row-name-' + row.id"
              class="text-base"
              :class="row.enabled == true ? 'disabled-name' : 'enabled-name'"
            >{{ row.name }}</span>
          </template>

          <!-- Document type column -->
          <template #body-cell-doc_type="{ row }">
            <span
              class="text-base"
              :class="row.enabled == true ? 'disabled-name' : 'enabled-name'"
            >{{ formatTextAndTranslate(row.doc_type).toUpperCase() }}</span>
          </template>

          <!-- Last modified by column -->
          <template #body-cell-last_modified_by="{ row }">
            {{ getUserName(row.last_modified_by) }}
          </template>

          <!-- Last modified on column -->
          <template #body-cell-last_modified_on="{ row }">
            {{ row.last_modified_on ? formatDateAccordingToPreference(row.last_modified_on) : '-' }}
          </template>
        </DocBitsTable>
      </div>
    </div>

      <!-- Add Decision Tree Window -->
      <q-dialog v-model="dialog" @hide="resetFields" @escape-key="closeDialog">
        <q-card class="card">
          <q-toolbar class="bg-primary">
            <q-toolbar-title class="text-white">
              <span class="text-weight-bold text-center text-lg">
                {{ isEditMode ? $t('edit_tree') : $t('create_new_tree') }}
              </span>
            </q-toolbar-title>
            <q-btn flat round dense icon="close" @click="closeDialog" v-close-popup />
          </q-toolbar>

          <q-card-section class="row">
            <q-input
              v-model="decisionTableName"
              data-test="decision-tree-name-input"
              placeholder="Decision Tree Name"
              dense
              outlined
              :error="decisionTableNameError"
              :error-message="$t('field_required')"
              class="col-12 card-padding"
            />

            <q-select
              v-model="selectedDocumentKey"
              data-test="decision-tree-doctype-select"
              :options="docTypes"
              option-label="title"
              option-value="key"
              label="Document Type"
              dense
              outlined
              class="col-12 card-padding"
              :error="documentKeyError"
              :error-message="$t('field_required')"
              menu-anchor="bottom left"
              menu-self="top left"
              transition-show="jump-down"
              transition-hide="jump-up"
              emit-value
              map-options
            />
          </q-card-section>
          <q-card-actions align="right">
            <f-btn
              flat
              data-test="decision-tree-cancel-btn"
              :label="$t('cancel')"
              @click="closeDialog"
              appearance="cancel"
            />
            <f-btn
              flat
              data-test="decision-tree-save-btn"
              :label="$t('save')"
              @click="validateAndSubmit"
              class="mr-2"
            />
          </q-card-actions>
        </q-card>
      </q-dialog>
      <!-- End Of The Add Decision Tree Window -->

      <!-- Start Of The Decision Tree Import Window -->
      <q-dialog v-model="uploadDialog">
        <q-card style="width: 20vw">
          <q-toolbar class="text-white secondary-toolbar">
            <q-toolbar-title
              ><span class="text-weight-bold">
                {{ $t('import_decision_tree') }}
              </span>
            </q-toolbar-title>
            <q-btn flat round dense icon="close" v-close-popup />
          </q-toolbar>

          <q-card-section>
            <div class="input-fields mb-2.5">
              <Icon icon="mdi:export" width="64" height="64" />
              <div class="mt-2.5">
                {{ $t('import_field_decision_tree') }}
              </div>
            </div>
            <q-file
              color="white"
              data-cy="upload-multiple-docs"
              data-test="decision-tree-import-file"
              label-color="white"
              outlined
              @update:model-value="uploadFile"
              v-model="uploadedFile"
              :label="$t('import_decision_tree')"
              flat
              dense
              round
            >
              <template v-slot:prepend>
                <Icon icon="mdi:paperclip" class="size-4" />
              </template>
              <template v-slot:file="{ index, file }">
                <div class="text-white">
                  {{ file.name }}
                </div>
                <q-tooltip>
                  {{ file.name }}
                </q-tooltip>
                <span v-if="false"> {{ index }} </span>
              </template>
            </q-file>
          </q-card-section>
        </q-card>
      </q-dialog>
      <!-- End Of The Decision Tree Import Window -->
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { ref, defineComponent, computed } from 'vue';
import { Icon } from '@iconify/vue';
import { storeToRefs } from 'pinia';
import { decisionApiService } from 'src/services/index';
import { documentTypeApiService } from 'src/services/index';
import { UUID } from 'crypto';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import { supplierDocTypeKey } from 'src/constants';
import displayFieldLabel from 'src/utils/displayFieldLabel.js';
import dateUtils from 'src/utils/date';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
} from 'src/components/Table';
import { useTranslate } from '@tolgee/vue';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';

export default defineComponent({
  name: 'decisionTree',
  components: {
    Icon,
    Loader,
    DocBitsTable,
  },
  mixins: [helperMixin, displayFieldLabel, dateUtils],
  data() {
    return {
      workflowId: ref(''),
      searchBy: ref(''),
      tableData: ref([] as any),
      filteredData: ref([] as any),
      confirmDelete: ref(false),
      selectedRecordIndex: ref(),
      version: ref(''),
      dialog: ref(false),
      decisionTableNameError: false,
      documentKeyError: false,
      docTypes: [] as { title: string; key: string }[],
      supplierDocTypeKey,
    };
  },
  methods: {
    filterTableData() {
      if (!this.searchBy) {
        this.filteredData = this.tableData;
        return;
      }
      this.filteredData = this.tableData.filter(
        (row: any) =>
          row.name
            .toLowerCase()
            .includes(this.searchBy.toLowerCase()) as string,
      );
    },

    async addDecisionTable() {
      try {
        let formdata = new FormData();
        formdata.append('name', this.decisionTableName);
        formdata.append('doc_type', this.selectedDocumentKey);
        formdata.append('data', this.treeData);
        formdata.append('tree_id', this.selectedTreeId);
        this.showLoading();
        const response =
          await decisionApiService.saveDecisionTreeRecord(formdata);
        if (response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }
        this.init();
        notify.success(response.message);
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.hideLoading();
      }
    },

    async uploadFile(file: any) {
      try {
        this.showLoading();
        this.uploadDialog = false;
        let formData = new FormData();
        formData.append('file', file);
        const response = (await decisionApiService.importDecisionTree(
          formData,
        )) as dynamicObj;
        if (response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }
        notify.success(response.message);
        this.init();
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.hideLoading();
      }
    },

    async deleteTable(id: UUID) {
      try {
        this.showLoading();
        const response = (await decisionApiService.deleteTable(
          id,
        )) as dynamicObj;
        if (response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }
        notify.success(response.message);
        this.init();
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.hideLoading();
      }
    },

    async init(use_cache = false) {
      try {
        this.isLoading = true;
        this.showLoading();
        const response =
          await decisionApiService.getAllDecisionTrees(use_cache);
        if (!response.hasOwnProperty('success') || response.success === false) {
          throw response;
        }
        this.tableData = response.data;
        this.filteredData = this.tableData;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.isLoading = false;
        this.hideLoading();
      }
    },

    openTreeDesigner(row: any) {
      this.$router.push('/settings/decision-tree-designer/' + row.id);
    },

    handleRowAction(payload: RowActionPayload) {
      const row = payload.row;
      if (payload.action === 'edit') {
        this.openEditTreeDialog(row);
      } else if (payload.action === 'delete') {
        this.confirmDelete = true;
        this.deleteTable(row.id);
      }
    },

    handleRowClick(payload: { row: any }) {
      this.openTreeDesigner(payload.row);
    },

    async loadDocTypes() {
      try {
        this.showLoading();
        const response = await documentTypeApiService.fetchDocTypes();

        this.docTypes = response.data
          .filter(
            (document: { document_key: any }) =>
              !supplierDocTypeKey.includes(document.document_key),
          )
          .map(
            (document: {
              translation_key: any;
              title: any;
              document_key: any;
            }) => ({
              title: this.$t(document.translation_key),
              key: document.document_key,
            }),
          );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    validateAndSubmit() {
      this.decisionTableNameError = !this.decisionTableName;
      this.documentKeyError = !this.selectedDocumentKey;

      if (!this.decisionTableNameError && !this.documentKeyError) {
        this.addDecisionTable();
        this.closeDialog();
      }
    },

    resetFields() {
      this.decisionTableName = '';
      this.selectedDocumentKey = '';
      this.decisionTableNameError = false;
      this.documentKeyError = false;
      this.isEditMode = false;
      this.selectedTreeId = '';
    },

    openEditTreeDialog(row: any) {
      this.isEditMode = true;
      this.selectedTreeId = row.id;
      this.decisionTableName = row.name;
      this.selectedDocumentKey = row.doc_type;
      this.dialog = true;
    },

    closeDialog() {
      this.dialog = false;
      this.resetFields();
    },

    getUserName(userId: string): string {
      if (!userId) return '-';
      const user = this.usersMap.get(Number(userId));
      if (user) {
        return `${user.first_name} ${user.last_name}`;
      }
      return userId;
    },
  },
  mounted() {
    this.prepareUsersDropdown();
    this.init(true);
    this.loadDocTypes();
    this.filterTableData();
  },
  setup() {
    const { t } = useTranslate();
    const decisionTableName = ref('');

    // Users dropdown for resolving user names
    const dropdownStore = useDropdownStore();
    const { usersMap } = storeToRefs(dropdownStore);
    const { prepareUsersDropdown } = dropdownStore;

    // Column definitions for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'name',
        label: t.value('name'),
        field: 'name',
        sortable: true,
        align: 'left',
        style: 'width: 40%',
        filter: true,
      },
      {
        name: 'doc_type',
        label: t.value('document_type'),
        field: 'doc_type',
        sortable: true,
        align: 'left',
        filter: true,
      },
      {
        name: 'last_modified_by',
        label: t.value('last_modified_by'),
        field: 'last_modified_by',
        sortable: true,
        align: 'left',
        style: 'width: 150px',
        filter: false,
      },
      {
        name: 'last_modified_on',
        label: t.value('last_modified_at'),
        field: 'last_modified_on',
        sortable: true,
        align: 'left',
        style: 'width: 150px',
        filter: false,
      },
    ]);

    // Row actions for edit and delete
    const rowActions: RowActionItem[] = [
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
        color: 'primary',
      },
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
      },
    ];

    return {
      decisionTableName,
      documentList: [] as string[],
      selectedDocumentKey: ref(''),
      selectedDocumentTypeFields: {} as any,
      uploadedFile: ref(),
      uploadDialog: ref(false),
      isEditMode: ref(false),
      selectedTreeId: ref(''),
      columns,
      rowActions,
      isLoading: ref(false),
      usersMap,
      prepareUsersDropdown,
      t,
    };
  },
});
</script>

